    "settings.title": "Akkaunt sozlamalari", "settings.eyebrow": "Akkauntingiz", "settings.intro": "Ma’lumotlaringiz dolzarb bo‘lsin — ular biz tayyorlagan har bir hujjat va yuborgan har bir xabarda ishlatiladi.", "settings.profile": "Shaxsiy ma’lumotlar", "settings.profileBody": "Pasportdagi kabi ismingiz va jamoamiz bog‘lana oladigan telefon raqami.", "settings.fullName": "To‘liq ism (pasportdagidek)", "settings.phone": "Telefon / WhatsApp", "settings.email": "Email", "settings.emailNote": "Email — kirish manzilingiz, bu yerda o‘zgartirib bo‘lmaydi. Yangilash kerak bo‘lsa bizga yozing.", "settings.save": "Saqlash", "settings.saved": "✓ Ma’lumotlaringiz saqlandi.", "settings.password": "Parol", "settings.passwordBody": "Kirish uchun parol o‘rnating yoki o‘zgartiring. Istalgan vaqtda email kodidan ham foydalanishingiz mumkin.", "settings.newPassword": "Yangi parol", "settings.confirmPassword": "Yangi parolni tasdiqlang", "settings.updatePassword": "Parolni yangilash", "settings.passwordUpdated": "✓ Parolingiz yangilandi.", "settings.danger": "Akkauntni o‘chirish", "settings.dangerBody": "Jarayondagi ariza yo‘qligini tasdiqlagach, akkauntingiz va yuklangan fayllarni o‘chiramiz. Qonun talab qilgan yozuvlar faqat talab qilingan muddatgacha saqlanadi.", "settings.reason": "Sabab (ixtiyoriy)", "settings.confirmDelete": "Akkauntim va fayllarim butunlay o‘chirilishini tushunaman.", "settings.requestDelete": "O‘chirishni so‘rash", "settings.deletionSent": "✓ So‘rov qabul qilindi. 5 ish kuni ichida email orqali tasdiqlaymiz.", "settings.card": "Akkaunt sozlamalari", "settings.cardBody": "Ism, telefon raqami, parol va akkauntni o‘chirish.", "settings.back": "Boshqaruv paneli",
